mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM watchlist_item
    WHERE watchlist_id = #{watchlistId}
      AND ticker_symbol = #{tickerSymbol}
)

mapper.delete:
DELETE FROM watchlist_item
WHERE watchlist_id = #{watchlistId}
  AND UPPER(ticker_symbol) = UPPER(#{tickerSymbol})

mapper.update:
UPDATE watchlist_item
SET alert_status = 'TRIGGERED',
    alert_triggered_at = #{triggeredAt},
    alert_trigger_price = #{triggerPrice},
    alert_delivery = 'PENDING',
    alert_delivery_attempts = 0
WHERE watchlist_id = #{watchlistId}
  AND ticker_symbol = #{tickerSymbol}
  AND alert_status = 'ACTIVE'
  AND alert_direction = #{direction}
  AND alert_target_price = #{targetPrice}

UPDATE watchlist_item
SET alert_delivery = #{delivery},
    alert_delivery_attempts = alert_delivery_attempts + 1
WHERE watchlist_id = #{watchlistId}
  AND ticker_symbol = #{tickerSymbol}
  AND alert_status = 'TRIGGERED'
